<?php
 namespace QQWorld\Test\Integrity\Modular; use QQWorld\Framework\Component\ComponentRegistrar; class ImportConfigFilesTest extends \PHPUnit\Framework\TestCase { protected $_model; public function setUp() { $objectManager = \QQWorld\TestFramework\Helper\Bootstrap::getObjectManager(); $moduleDirSearch = $objectManager->get(\QQWorld\Framework\Component\DirSearch::class); $fileIteratorFactory = $objectManager->get(\QQWorld\Framework\Config\FileIteratorFactory::class); $xmlFiles = $fileIteratorFactory->create( $moduleDirSearch->collectFiles(ComponentRegistrar::MODULE, 'etc/{*/import.xml,import.xml}') ); $validationStateMock = $this->createMock(\QQWorld\Framework\Config\ValidationStateInterface::class); $validationStateMock->expects($this->any())->method('isValidationRequired')->will($this->returnValue(true)); $fileResolverMock = $this->createMock(\QQWorld\Framework\Config\FileResolverInterface::class); $fileResolverMock->expects($this->any())->method('get')->will($this->returnValue($xmlFiles)); $objectManager = \QQWorld\TestFramework\Helper\Bootstrap::getObjectManager(); $this->_model = $objectManager->create( \QQWorld\ImportExport\Model\Import\Config\Reader::class, ['fileResolver' => $fileResolverMock, 'validationState' => $validationStateMock] ); } public function testImportXmlFiles() { $this->_model->read('global'); } } 